function sourceOf(value: string): string {
  for (const [de, variants] of Object.entries(translations)) {
    if (de === value || Object.values(variants).includes(value)) return de
  }
  return value
}

export function translate(value: string, language: Language): string {
  const trimmed = value.trim()
  if (!trimmed) return value
  const source = sourceOf(trimmed)
  const next = language === 'de' ? source : translations[source]?.[language] || source
  return next === trimmed ? value : value.replace(trimmed, next)
}

const TRANSLATED_ATTRS = ['alt', 'placeholder', 'aria-label']

type ContextValue = { language: Language; setLanguage: (language: Language) => void }
const I18nContext = createContext<ContextValue>({ language: 'de', setLanguage: () => undefined })

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('site-language') as Language) || 'de')
  useEffect(() => { localStorage.setItem('site-language', language); document.documentElement.lang = language }, [language])
  const value = useMemo(() => ({ language, setLanguage }), [language])
  return <I18nContext.Provider value={value}><PageTranslator language={language}/>{children}</I18nContext.Provider>
}

function PageTranslator({ language }: { language: Language }) {
  useEffect(() => {
    const run = () => {
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
      const nodes: Text[] = []
      while (walker.nextNode()) nodes.push(walker.currentNode as Text)
      for (const node of nodes) {
        const raw = node.nodeValue || ''; if (!raw.trim()) continue
        const next = translate(raw, language)
        if (next !== raw) node.nodeValue = next
      }
      for (const attr of TRANSLATED_ATTRS) {
        document.querySelectorAll(`[${attr}]`).forEach(el => {
          const raw = el.getAttribute(attr) || ''; if (!raw.trim()) return
          const next = translate(raw, language)
          if (next !== raw) el.setAttribute(attr, next)
        })
      }
    }
    const timer = requestAnimationFrame(run)
    const observer = new MutationObserver(run); observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: TRANSLATED_ATTRS })
    return () => { cancelAnimationFrame(timer); observer.disconnect() }
  }, [language])
  return null
}

export const useI18n = () => useContext(I18nContext)
